      // 4. Central Raised Roller Conveyor Belt (x = 0.11R..0.27R, y = -0.56R..+0.44R)
      const cx0 = 0.11 * R, cx1 = 0.27 * R, cy0 = -0.56 * R, cy1 = 0.44 * R;
      const zConvB = zPlat + 0.08 * R * H, zConvT = zPlat + 0.14 * R * H;
