      pushBox3D(faces, proj, 0.22 * r * SS, 0.46 * r * SS, -0.48 * r, 0.48 * r, z0, z0 + 0.56 * r * H, '#1e293b', seamCol, 0.82, 1.15);
      pushHazardRamp3D(faces, proj, 0.42 * r * SS, 0.84 * r, -0.52 * r, 0.52 * r, z0, z0 + 0.08 * r * H, seamCol);
